head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "";
scwin.vScrenID = "ULDSTF05628.xml";
scwin.vParentScrenID = "";
scwin.vScrenTpCD = "";
scwin.vBzProcsNo;
scwin.vSecugrpID;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetPar = function(arrPar) {
    // 업종선택팝업에서 사용할 인수를 지정하는 펑션
    arrPar[0] = "";
    arrPar[1] = "";
    return arrPar.length;
};
scwin.fn_SetPar = function(arrPar) {
    /*
    gAfStdIndCd = arrPar[0].STD_IND_CD;
    if (js_market == '1') {
    	edt_Afchg_Std_Ind_Cd.text = arrPar[0].STD_IND_CD;
    } else if (js_market == '2') {
    	edt_Afchg_Std_Ind_Cd.text = arrPar[0].KOSDAQ_STD_IND_CD;
    }
    */
    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
    txb_COM_NM.setValue(arrPar[0].COM_NM);
    scwin.fn_getBfChgAcntcls_read_sync();
};
scwin.fn_read_sync = function() {
    var url = "/fiscalYearChange.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=exstreadMarket&inputMessageId=FISCYY_CHG_INOUT" + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
    dts_FiscyyChg.DataID = encodeURI(url);
    dts_FiscyyChg.Reset();
};
scwin.fn_getBfChgAcntcls_read_sync = function() {
    var url = "/fiscalYearChange.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=getBfChgExstStrtDd&inputMessageId=BFCHG_ACNTCLS_OUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    dts_BfChgAcntcls.DataID = encodeURI(url);
    dts_BfChgAcntcls.Reset();
};
scwin.fn_checkInsertable = function(IsurCd) {
    var url = "/fiscalYearChange.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01; //  01 List
    url += "&method=exstlistMarket&inputMessageId=FISCYY_CHG_INOUT&ISUR_CD=" + IsurCd;
    url += "&STYPE=1";
    url += "&BZ_SDATE=";
    url += "&BZ_EDATE=";
    url += "&BF_EXST_MODIFY_YN=";
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    var rowCnt = dts_List.getTotalRow();
    if (rowCnt == 0) {
        return true;
    } else {
        return false;
    }
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_COM_NM) == "") {
        $c.win.alert("[회사]를 선택하세요.");
        txb_COM_NM.focus();
        return false;
    }
    //if (getObjectValue(edt_Mktact_bfchgexst_start_Dd) == "") {
    //	alert("[변경전 존립개시일]을 입력하세요.");edt_Mktact_bfchgexst_start_Dd.focus();return false;
    //}
    //if (getObjectValue(edt_Mktact_bfchgexst_end_Dd) == "") {
    //	alert("[변경전 존립종료일]을 입력하세요.");edt_Mktact_bfchgexst_end_Dd.focus();return false;
    //}
    if ($c.stf.getObjectValue(edt_Mktact_afchgexst_start_Dd) == "") {
        $c.win.alert("[변경후 존립개시일]을 입력하세요.");
        edt_Mktact_afchgexst_start_Dd.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_Mktact_afchgexst_end_Dd) == "") {
        $c.win.alert("[변경후 존립종료일]을 입력하세요.");
        edt_Mktact_afchgexst_end_Dd.focus();
        return false;
    }
    if (parseInt(edt_Mktact_afchgexst_start_Dd.getValue(), '10') > parseInt(edt_Mktact_afchgexst_end_Dd.getValue(), '10')) {
        $c.win.alert("[변경후 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        edt_Mktact_afchgexst_start_Dd.focus();
        return false;
    } else if (parseInt(edt_Mktact_afchgexst_start_Dd.getValue(), '10') == parseInt(edt_Mktact_afchgexst_end_Dd.getValue(), '10')) {
        $c.win.alert("[변경후 시작일과  종료일 같으면 안됩니다.]다시 입력해주세요");
        return false;
    }
    if ($c.stf.getObjectValue(edt_MKTACT_ENFORCE_DD) == "") {
        $c.win.alert("[변경일]을 입력하세요.");
        edt_MKTACT_ENFORCE_DD.focus();
        return false;
    }

    //if ((vCurDate >= parseInt(edt_MKTACT_ENFORCE_DD.Text,'10') )) {
    //	alert("[변경일]을 현재일이후로 입력하세요");edt_MKTACT_ENFORCE_DD.focus();return false;
    //}
    return true;
};
scwin.fn_save = function() {
    //Check Insertable
    if (!scwin.fn_checkInsertable($c.stf.getObjectValue(txb_ISUR_CD))) {
        $c.win.alert($c.stf.getObjectValue(txb_ISUR_CD) + " " + $c.stf.getObjectValue(txb_COM_NM) + " 회사코드(명)이  존립기간 관리에 이미 존재합니다.");
        return;
    }
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess('I')) // Message Box 
            return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        scwin.fr_bz_procs_no = scwin.vBzProcsNo;
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            scwin.Isur_cd = $c.stf.getObjectValue(txb_ISUR_CD); /*ORG SRC: dts_FiscyyChg.UserStatus(1) = TB_JOB_INSERT;*/ X = TB_JOB_INSERT;
            dts_FiscyyChg.setCellData(1, "ISUR_CD", scwin.Isur_cd); //회사코드를 바인딩한다.
            dts_FiscyyChg.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            var url = "/fiscalYearChange.do";
            url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
            url += "&method=exstMarketDisclsCal&inputMessageId=FISCYY_CHG_INOUT";
            url += "&AFCHG_EXST_END_DD=" + $c.stf.getObjectValue(edt_Mktact_afchgexst_end_Dd);
            dts_BzDisclsCal.DataID = encodeURI(url);
            dts_BzDisclsCal.Reset();
            dts_FiscyyChg.setCellData(1, "ADMISUNOTI_DD", dts_BzDisclsCal.getCellData(1, "ADMISUNOTI_DD"));
            dts_FiscyyChg.setCellData(1, "ADMISU_DISCLS_DD", dts_BzDisclsCal.getCellData(1, "ADMISU_DISCLS_DD"));
            dts_FiscyyChg.setCellData(1, "ADMISU_DESIGN_DD", dts_BzDisclsCal.getCellData(1, "ADMISU_DESIGN_DD"));
            dts_FiscyyChg.setCellData(1, "DELIST_ADVNOTI_DD", dts_BzDisclsCal.getCellData(1, "DELIST_ADVNOTI_DD"));
            dts_FiscyyChg.setCellData(1, "DELIST_DISCLS_DD", dts_BzDisclsCal.getCellData(1, "DELIST_DISCLS_DD"));
            dts_FiscyyChg.setCellData(1, "DELIST_DD", dts_BzDisclsCal.getCellData(1, "DELIST_DD"));
            scwin.fn_trs();
        }
    }
};
scwin.fn_update = function() {
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess('U')) // Message Box

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            return; /*ORG SRC: dts_FiscyyChg.UserStatus(1) = TB_JOB_UPDATE;*/ X = TB_JOB_UPDATE;
        dts_FiscyyChg.setCellData(1, "ISUR_CD", scwin.Isur_cd);
        dts_FiscyyChg.setCellData(1, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
        var url = "/fiscalYearChange.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=exstMarketDisclsCal&inputMessageId=FISCYY_CHG_INOUT";
        url += "&AFCHG_EXST_END_DD=" + $c.stf.getObjectValue(edt_Mktact_afchgexst_end_Dd);
        dts_BzDisclsCal.DataID = encodeURI(url);
        dts_BzDisclsCal.Reset();
        dts_FiscyyChg.setCellData(1, "ADMISUNOTI_DD", dts_BzDisclsCal.getCellData(1, "ADMISUNOTI_DD"));
        dts_FiscyyChg.setCellData(1, "ADMISU_DISCLS_DD", dts_BzDisclsCal.getCellData(1, "ADMISU_DISCLS_DD"));
        dts_FiscyyChg.setCellData(1, "ADMISU_DESIGN_DD", dts_BzDisclsCal.getCellData(1, "ADMISU_DESIGN_DD"));
        dts_FiscyyChg.setCellData(1, "DELIST_ADVNOTI_DD", dts_BzDisclsCal.getCellData(1, "DELIST_ADVNOTI_DD"));
        dts_FiscyyChg.setCellData(1, "DELIST_DISCLS_DD", dts_BzDisclsCal.getCellData(1, "DELIST_DISCLS_DD"));
        dts_FiscyyChg.setCellData(1, "DELIST_DD", dts_BzDisclsCal.getCellData(1, "DELIST_DD"));
        scwin.fn_trs();
    }
};
scwin.fn_delete = function() {
    if (!$c.lc.fn_isProcess('D')) // Message Box

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        return; /*ORG SRC: dts_FiscyyChg.UserStatus(1) = TB_JOB_DELETE;*/ X = TB_JOB_DELETE;
    scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    dts_FiscyyChg.setCellData(1, "ISUR_CD", scwin.Isur_cd);
    dts_FiscyyChg.setCellData(1, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    trs_Delete.Action = "/fiscalYearChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=exstsaveMarket";
    trs_Delete.KeyName = "toinb_dataid4";
    trs_Delete.KeyValue = "JSP(I:pInput=dts_FiscyyChg)";
    trs_Delete.Post();
};
scwin.fn_trs = function() {
    if (dts_FiscyyChg.UserStatus(1) == '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (dts_FiscyyChg.UserStatus(1) == '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    }
    trs_Save.Action = $c.lc.fn_encodeNSession("/fiscalYearChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=exstsaveMarket");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_FiscyyChg)";
    trs_Save.Post();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.fn_dscl = async function() {
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68066";
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = scwin.Isur_cd;
        arr[3] = scwin.Mkt_id;
        $c.stf.CopyDataSet(dts_FiscyyChg, param_dts_mst);
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_drft = function() {

};
scwin.fn_makt = function() {

};
scwin.img_MKTACT_ENFORCE_DD_onclick = function() {
    popUpCalendar2(edt_MKTACT_ENFORCE_DD);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_FiscyyChg_OnLoadError = function() {
    $c.stf.alert_error(dts_FiscyyChg);
};
scwin.dts_FiscyyChg_OnLoadCompleted = function(rowcount) {

};
scwin.dts_BfChgAcntcls_OnLoadError = function() {
    $c.stf.alert_error(dts_BfChgAcntcls);
};
scwin.dts_BfChgAcntcls_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(edt_Mktact_bfchgexst_start_Dd, dts_BfChgAcntcls.getCellData(1, "BFCHG_EXST_STRT_DD"));
    $c.stf.setObjectValue(edt_Mktact_bfchgexst_end_Dd, dts_BfChgAcntcls.getCellData(1, "BFCHG_EXST_END_DD"));
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_Delete_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');

    // ReFresh
    scwin.fn_read_sync();

    // Parent ReFresh
    scwin.fn_parentRefresh();
    buttonSet.setUpdateStatus();
    $c.stf.showObj(img_COM_NM, false);
};
scwin.trs_Delete_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_parentRefresh();
    //buttonSet.setInsertStatus();
    await $c.frame.CloseFrame();
};
scwin.img_AFCHG_EXST_END_DD_onclick = function() {
    popUpCalendar2(edt_Mktact_afchgexst_end_Dd);
};
scwin.img_AFCHG_EXST_STRT_DD_onclick = function() {
    popUpCalendar2(edt_Mktact_afchgexst_start_Dd);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    var fnc = $c.frame.path("../").scwin.fn_GetPar;
    var arrPar = new Array();
    fnc(arrPar); // Provider callback
    scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : "");
    scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : "");
    scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : "");
    scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : "");
    scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : "");
    var parentWin = $c.frame.path("../");
    scwin.vSecugrpID = parentWin.scwin.vSecugrpID;
    scwin.vParentScrenID = parentWin.scwin.vScrenID;

    /* buttonSet Event*/
    buttonSet.setSaveInfo(btn_Save, fn_save);
    buttonSet.setUpdateInfo(btn_Update, fn_update);
    buttonSet.setDeleteInfo(btn_Delete, fn_delete);
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl);
    dts_FiscyyChg.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=FISCYY_CHG_INOUT";
    dts_FiscyyChg.reset();
    dts_FiscyyChg.insertRow();
    var vCurDate = $c.ut.cGetToday("yyyymmdd"); //Modify Date 
    $c.stf.setObjectValue(edt_MKTACT_ENFORCE_DD, scwin.vCurDate);
    $c.stf.showObj(img_MKTACT_ENFORCE_DD, false);
    if (scwin.Isur_cd != "") {
        // Modify Mode
        $c.stf.setObjectValue(txb_ISUR_CD, scwin.Isur_cd);
        $c.stf.setObjectValue(txb_COM_NM, scwin.Isur_nm);
        $c.stf.showObj(img_COM_NM, false);
        buttonSet.setUpdateStatus();
        scwin.fn_read_sync();
    } else {
        // Insert  Mode
        $c.stf.showObj(img_COM_NM, true);
        buttonSet.setInsertStatus();
    }
};
scwin.img_COM_NM_onclick = function() {
    //show SPAC  List
    $c.lc.fn_PopFindCorpChrgSW(scwin.vSecugrpID, "1");
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {

};
